<div class="form-grid"><label>Pelanggan <select name="customer_id" required><option value="">Pilih pelanggan</option>@foreach($customers as $customer)<option value="{{ $customer->id }}" @selected((string) old('customer_id', $booking->customer_id ?? '') === (string) $customer->id)>{{ $customer->code }} · {{ $customer->name }}</option>@endforeach</select></label><label>Pakej rawatan <select name="treatment_package_id"><option value="">Tanpa pakej</option>@foreach($packages as $package)<option value="{{ $package->id }}" @selected((string) old('treatment_package_id', $booking->treatment_package_id ?? '') === (string) $package->id)>{{ $package->name }} · RM {{ number_format($package->price, 2) }}</option>@endforeach</select></label><label>Tarikh & masa <input type="datetime-local" name="starts_at" value="{{ old('starts_at', isset($booking) ? $booking->starts_at->format('Y-m-d\TH:i') : '') }}" required></label><label>Status <select name="status"><option value="confirmed" @selected(old('status', $booking->status ?? 'confirmed') === 'confirmed')>Disahkan</option><option value="completed" @selected(old('status', $booking->status ?? '') === 'completed')>Selesai</option><option value="cancelled" @selected(old('status', $booking->status ?? '') === 'cancelled')>Dibatalkan</option></select></label></div>
